  screen('infused-packaging','quality','Quality · infused packaging','Review infused batch packaging','HB-261028-I · labels, seals and product identity',()=>`${field('infusedPackagingEvidence','Packaging and label evidence','',{required:true})}${check('infusedPackagingChecked','I reviewed labels, ingredients, seals and all packaging requirements')}${callout('Publication needs separate approval','A packaging decision does not publish a page.','info')}`,'!infused-packaging','Release finished batch',{...quality,back:'infused-label'});
  const publicIngredients=()=>s.infusion?.ingredients.map(l=>`<li>${esc(l.name)} — ${l.fate==='Remains in product'?'used for infusion and remains in the product':'used for infusion, then removed'}.</li>`).join('')||'<li>Vanilla — used for infusion, then removed.</li><li>Rosemary — used for infusion, then removed.</li>';
  const approvedSources=()=> (s.infusion?.honey||honey).map(l=>card(`<h3>${esc(l.id==='H-108'?'Shea Grove · Grace':'River apiary · Rose')}</h3>${summary([['Source area',esc(l.area)],['Collected on',esc(l.collected)],['Harvest timing',esc(l.harvest)],['Forage',esc(l.forage)]])}<p>${l.id==='H-108'?'Grace tends hives among shea trees.':'Rose tends hives near coffee and seasonal flowers.'}</p>`)).join('');
